enum Edit { Insert { pos: usize, text: String }, Delete { pos: usize, len: usize } }

fn apply(doc: &mut Document, e: &Edit) {
    match e {
        Edit::Insert { pos, text } => doc.insert(*pos, text),
        Edit::Delete { pos, len } => doc.delete(*pos, *len),
    }
}

let mut history: Vec<Edit> = Vec::new();   // replay = re-match the log

