trait Command { fn execute(&mut self); fn undo(&mut self); }

struct InsertText { doc: Document, text: String }
impl Command for InsertText {
    fn execute(&mut self) { self.doc.insert(&self.text); }
    fn undo(&mut self) { self.doc.delete_last(self.text.len()); }
}

let mut history: Vec<Box<dyn Command>> = Vec::new();
